        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return int(v[0]), int(v[1])
            except Exception:
                return default
        return default

    def _sign(n):
        return 0 if n == 0 else (1 if n > 0 else -1)

    def _step_toward(a, b):
        ax, ay = _pair(a)
        bx, by = _pair(b)
        return [_sign(bx - ax), _sign(by - ay)]

    def _step_away(a, b):
        ax, ay = _pair(a)
        bx, by = _pair(b)
        return [_sign(ax - bx), _sign(ay - by)]

    def _best_target(points, sx, sy, prefer_far=False):
        best = None
        best_score = None
        for p in points or []:
            px, py = _pair(p, None)
            if px is None:
                continue
            score = abs(px - sx) + abs(py - sy)
            if prefer_far:
